  await page.evaluate(eid=>{activateWorkspaceTab('inspect');showElement(eid);},target.eid);assert.match(await page.locator('#inspect-rf-assessment').innerText(),/estimat/i);assert.match(await page.locator('#inspect-rf-assessment').innerText(),/0\.75/);
  await page.locator('#inspect-edit-property').click();await applyDialog(page,3);await page.waitForFunction(eid=>state.rfVisibleElementIds&&!state.rfVisibleElementIds.has(eid),target.eid);await popup.waitForFunction(pid=>!document.querySelector('.rf-value[data-pid="'+pid+'"]'),manifest.pid);
  assert.match(await page.locator('#inspect-rf-assessment').innerText(),/1\.5/);assert.match(await page.locator('#inspect-rf-assessment').innerText(),/estimat/i);checks.push('Editing through Inspect updates the minimum RF/mode, table and 3D field together; a passing element disappears when failing-only display is active.');
